    /** Type Default: 'VERT_NORMAL'. */
    type?: H.In<E.MeshSelectSimilarType>;
    /**
     * Compare Default: 'EQUAL'.
     * - `EQUAL`: Equal
     * - `GREATER`: Greater
     * - `LESS`: Less
     */
    compare?: H.In<"EQUAL" | "GREATER" | "LESS">;
    /** Threshold Default: 0.0. */
    threshold?: H.In<number>;
